/**
 * figma_get_node_detail — 预处理 Code Node
 * 全深度展开指定节点，返回完整 FigmaNode 结构
 *
 * 输入: Figma GET /v1/files/:key/nodes 响应
 * 输出: [{ json: { nodes: FigmaNode[] } }]
 */

const input = $input.first().json;
const params = $('When Executed by Another Workflow').first().json;
// MCP 的入参 schema 全是 string，agent 传 false 到达时是字符串 "false"（真值）。
// 必须先归一化，否则 include_styles 永远关不掉。
function asBool(v, dflt) {
  if (v === undefined || v === null || v === '') return dflt;
  if (typeof v === 'boolean') return v;
  return !['false', '0', 'no', 'off'].includes(String(v).trim().toLowerCase());
}

const includeStyles = asBool(params.include_styles, true);

// {r,g,b,a} 浮点 -> #rrggbb，读不出颜色的浮点噪音变成人能看懂的值
function toHex(c) {
  if (!c || typeof c.r !== 'number') return null;
  const h = (x) => Math.round(Math.max(0, Math.min(1, x)) * 255).toString(16).padStart(2, '0');
  return '#' + h(c.r) + h(c.g) + h(c.b);
}

function asInt(v, dflt, min, max) {
  const n = parseInt(v, 10);
  if (Number.isNaN(n)) return dflt;
  return Math.min(Math.max(n, min), max);
}

// 展开深度上限，默认 6。原实现无上限，深层设计稿会把输出撑爆。
const maxDepth = asInt(params.max_depth, 6, 1, 20);

// 全深度转换（maxDepth 设为 99 表示不限制）
function transformNode(node, currentDepth) {
  if (!node) return null;

  const result = {
    id: node.id,
    name: node.name || '',
    type: node.type || 'UNKNOWN',
  };
  // visible 默认为 true，只在反常（隐藏）时输出
  if (node.visible === false) result.hidden = true;

  if (node.type === 'TEXT') {
    result.characters = node.characters || '';
    if (includeStyles && node.style) {
      result.text_style = {
        font_family: node.style.fontFamily,
        font_size: node.style.fontSize,
        font_weight: node.style.fontWeight,
        text_align: node.style.textAlignHorizontal,
      };
    }
  }

  if (node.type === 'INSTANCE' && node.componentId) {
    result.component_id = node.componentId;
  }

  if (node.type === 'COMPONENT_SET' || node.type === 'COMPONENT') {
    if (node.componentPropertyDefinitions) {
      result.variants = {};
      for (const [key, def] of Object.entries(node.componentPropertyDefinitions)) {
        if (def.type === 'VARIANT') {
          result.variants[key] = def.variantOptions || [];
        }
      }
    }
  }

  if (node.absoluteBoundingBox) {
    result.layout = {
      width: Math.round(node.absoluteBoundingBox.width),
      height: Math.round(node.absoluteBoundingBox.height),
    };
    if (node.layoutMode && node.layoutMode !== 'NONE') {
      result.layout.layout_mode = node.layoutMode;
    }
  }

  // 样式信息
  if (includeStyles) {
    // Figma 的 color 是 {r,g,b,a} 浮点，序列化后形如
    // {"r":0.06666667014360428,"g":0.06666667014360428,...} —— 单个色值就要 80+ 字符，
    // 而且 agent 读不出这是什么颜色。转成 hex，既短又可读。
    const fills = (node.fills || []).filter(f => f.visible !== false).map(f => {
      const o = { type: f.type };
      const hex = toHex(f.color);
      if (hex) o.color = hex;
      if (f.opacity !== undefined && f.opacity !== 1) o.opacity = Math.round(f.opacity * 100) / 100;
      return o;
    });
    if (fills.length) result.fills = fills;
    const strokes = (node.strokes || []).filter(s => s.visible !== false).map(s => {
      const o = { type: s.type };
      const hex = toHex(s.color);
      if (hex) o.color = hex;
      return o;
    });
    if (strokes.length) result.strokes = strokes;
    if (node.cornerRadius) {
      result.corner_radius = node.cornerRadius;
    }
  }

  // 交互相关
  if (node.interactions && node.interactions.length > 0) {
    result.interactions = node.interactions.map(i => ({
      trigger: i.trigger?.type,
      action: i.actions?.[0]?.type,
      destination: i.actions?.[0]?.destinationId,
    }));
  }

  // 子节点展开。原本是无上限全深度递归——设计稿嵌套很深时输出会失控，
  // 这是「输出经常过大」的主要来源之一。加深度上限，到底时用 children_count 交代还有多少。
  if (node.children && node.children.length > 0) {
    if (currentDepth < maxDepth) {
      result.children = node.children
        .map(child => transformNode(child, currentDepth + 1))
        .filter(Boolean);
      if (!result.children.length) {
        delete result.children;
        result.children_count = node.children.length;
      }
    } else {
      // 未展开，用计数交代规模，并提示如何继续下钻
      result.children_count = node.children.length;
      result.truncated_at_depth = true;
    }
  }

  return result;
}

// --- 主逻辑 ---
const nodesMap = input.nodes || {};
const nodes = [];

for (const [nodeId, nodeData] of Object.entries(nodesMap)) {
  if (nodeData && nodeData.document) {
    const transformed = transformNode(nodeData.document, 0);
    if (transformed) {
      nodes.push(transformed);
    }
  }
}

return [{
  json: {
    nodes,
    count: nodes.length,
  }
}];

/**
 * 通用过滤 + 输出预算 Code Node — 所有 figma workflow 的最后一步
 *
 * 输入: 上游预处理结果（含 nodes / components / threads 之一）
 * 输出: 过滤 + 按 token 预算切片后的结果，附续取信息
 *
 * 为什么不用「最多 N 条」：
 *   旧实现是 MAX_RESULTS=200 的固定条数上限。条数和 token 不成比例 ——
 *   200 个浅层节点可能只有 3k token，而 200 条中文评论轻松超 20k。
 *   所以这里改成按 token 预算切，条数不设限。
 *
 * 为什么要 CJK 感知：
 *   英文 JSON 大约 4 字符/token，中文大约 1.5 字符/token，差 2.6 倍。
 *   评论正文是中文为主，用固定「字符数/4」估算会严重低估，切完照样超预算。
 *
 * 截断语义：不静默丢弃。超预算时返回 truncated=true + next_offset，
 * 并在 hint 里用中文写清怎么续取 —— 和 qa_experience_read 的翻页语义保持一致。
 * 切片边界永远落在完整条目（完整话题 / 完整顶层子树）上，不切碎结构。
 */

// MCP 单次响应上限 25000 token，留 20% 余量给外层包装和 hint 文本
const TOKEN_BUDGET = 20000;

const input = $input.first().json;
const params = $('When Executed by Another Workflow').first().json;
const filterCode = params.filter_code || '';

function asInt(v, dflt, min, max) {
  const n = parseInt(v, 10);
  if (Number.isNaN(n)) return dflt;
  return Math.min(Math.max(n, min), max);
}
const offset = asInt(params.offset, 0, 0, 1000000);

// CJK 感知的 token 估算：CJK 约 1.5 字符/token，其余约 4 字符/token
function estimateTokens(str) {
  if (!str) return 0;
  let cjk = 0;
  for (const ch of str) {
    const c = ch.codePointAt(0);
    if ((c >= 0x4e00 && c <= 0x9fff) || (c >= 0x3040 && c <= 0x30ff) ||
        (c >= 0xac00 && c <= 0xd7af) || (c >= 0xf900 && c <= 0xfaff)) cjk++;
  }
  const other = str.length - cjk;
  return Math.ceil(cjk / 1.5 + other / 4);
}

// --- 确定要处理哪个数组 ---
let data, varName, outputKey;
if (Array.isArray(input.nodes)) {
  data = input.nodes; varName = 'nodes'; outputKey = 'nodes';
} else if (Array.isArray(input.components)) {
  data = input.components; varName = 'components'; outputKey = 'components';
} else if (Array.isArray(input.threads)) {
  // filter_code 里变量名沿用 comments，对 agent 更直观
  data = input.threads; varName = 'comments'; outputKey = 'threads';
} else {
  return [{ json: input }];
}

// --- 执行 agent 传入的过滤 ---
let filtered = data;
let filterError = null;
if (filterCode) {
  try {
    const fn = new Function(varName, `return (${filterCode})`);
    const r = fn(data);
    if (!Array.isArray(r)) {
      filterError = 'filter_code 必须返回数组';
      filtered = [];
    } else {
      filtered = r;
    }
  } catch (e) {
    filterError = `filter_code 执行出错: ${e.message}`;
    filtered = [];
  }
}

const total = filtered.length;
const windowed = filtered.slice(offset);

// --- 按 token 预算逐条累加，切在完整条目边界 ---
const picked = [];
let used = 0;
let truncated = false;
for (const item of windowed) {
  const cost = estimateTokens(JSON.stringify(item));
  if (picked.length > 0 && used + cost > TOKEN_BUDGET) {
    truncated = true;
    break;
  }
  picked.push(item);
  used += cost;
  // 单条就超预算：已收下它保证有进展，但立即停下
  if (used > TOKEN_BUDGET) {
    truncated = windowed.length > picked.length;
    break;
  }
}

// --- 组装输出 ---
const output = {};
for (const [k, v] of Object.entries(input)) {
  if (k !== outputKey) output[k] = v;
}
output[outputKey] = picked;
output.returned = picked.length;
output.total = total;

if (offset > 0) output.offset = offset;
if (filterError) output.filter_error = filterError;

if (truncated) {
  const nextOffset = offset + picked.length;
  output.truncated = true;
  output.next_offset = nextOffset;
  output.hint =
    `输出达 token 预算，本次返回第 ${offset + 1}-${nextOffset} 条，共 ${total} 条。` +
    `把 offset=${nextOffset} 传回本工具可续取剩余部分；` +
    `或用 filter_code 收窄范围以减少无关内容。`;
}

return [{ json: output }];
